<div class="d-flex gap-2 mb-3"><?php foreach(['open'=>'Abertos','acknowledged'=>'Reconhecidos','resolved'=>'Resolvidos','all'=>'Todos'] as $k=>$label):?><a class="btn btn-sm <?=$status===$k?'btn-primary':'btn-light'?>" href="/master/incidentes?status=<?=$k?>"><?=$label?></a><?php endforeach;?></div>
